import subprocess,json,copy
def sh(c):
    r=subprocess.run(c,capture_output=True,text=True,timeout=119); return (r.stdout+r.stderr)
base=json.load(open('cand_a.json'))
sets={'m1':{'Kpi':1.0,'Kii':50.0,'Kpv':0.3,'Kiv':1.0},'m2':{'Kpi':0.3,'Kii':5.0,'Kpv':1.0,'Kiv':5.0},'m3':{'Kpi':1.0,'Kii':20.0,'Kpv':0.5,'Kiv':2.0}}
for k,ch in sets.items():
    s=copy.deepcopy(base); s['params'].update(ch); json.dump(s,open(f'c_{k}.json','w'))
    o=sh(['python','tools/grid_equivalent_replay.py',f'c_{k}.json','val/A_val_load_op1.csv'])
    o2=sh(['python','tools/check_submission.py',f'c_{k}.json','val/A_val_load_op1.csv'])
    print(k,[l for l in o.splitlines() if l.strip().startswith(('P ','Q '))], [l for l in o2.splitlines() if 'replay' in l or 'failed' in l])
